/**
 * The indexing formula of every inflation-adjusted amount in the 2027-only
 * federal rules, for projection.ts.
 *
 * INDEXED entries are generated from a reproduction of the IRS's own
 * computation: each `comps[i].ratio` is the exact cost-of-living ratio the
 * IRS applied for 2027 (the C-CPI-U for September 2025–August 2026 as first
 * published, an 11-month average because October 2025 was never published,
 * over the base year's index per § 1(f)(3); HSA on its § 223(g) March
 * window; the wage base and household threshold on SSA's average wage
 * index). base × ratio, rounded as `on`/`roundMode`/`roundCents` say,
 * reproduces every published 2027 amount exactly (test/projection.test.ts).
 * Sources: Rev. Proc. 2024-40, 2025-32, 2026-35 (amounts); BLS series
 * SUUR0000SA0 / CUUR0000SA0 via the St. Louis Fed ALFRED vintages (index);
 * SSA notices 89 FR 85276, 90 FR 49047, 91 FR 67380 (wage index).
 *
 * DERIVED entries are amounts the statute or the Rev. Proc. builds from an
 * indexed one (joint = 200%, married filing separately = 50%, EITC maximum =
 * rate × earned income amount, ...). LAW entries are set by statute.
 */

import type { Expr } from "@invaro/opentax-core";

export type IndexId = "c-cpi-u" | "awi";

/** a rule an amount sits in: optionally narrowed to filing-status cases and a path regex */
export type ParamSite = { id: string; statuses?: string[]; path?: string };

type Common = { id: string; label: string; statute: string; published2027: string; rules: ParamSite[] };
export type ProjectionParam =
  | (Common & {
      kind: "indexed";
      index: IndexId;
      /** base amount(s) in cents and the exact 2027 cost-of-living ratio [numerator, denominator] */
      comps: { baseCents: string; ratio: [string, string] }[];
      roundCents: string;
      roundMode: "down" | "nearest";
      /** rounding applies to the increase over the base (most § 1(f)-style provisions) or to the whole amount */
      on: "increase" | "amount";
      /** the wage base never decreases (Social Security Act § 230(c)) */
      neverDecreases?: boolean;
    })
  | (Common & {
      kind: "derived";
      /** Σ projected(param) × num / den, then rounded */
      terms: { param: string; num: string; den: string }[];
      roundCents: string;
      roundMode: "down" | "nearest";
    })
  | (Common & { kind: "law"; byYear: (year: number) => string });

