/**
 * § 164(b)(7): the SALT limitation is 101% of the preceding year's through
 * 2029 and $10,000 from 2030 (the phase-down no longer applies; with the cap
 * at the $10,000 floor it cannot reduce anything). The statute states no
 * rounding: amounts are kept to the cent, a sub-cent result rounded half up.
 */
const pctSteps = (start: bigint, from: number, year: number, lastYear: number): bigint => {
  let v = start;
  for (let y = from + 1; y <= Math.min(year, lastYear); y++) v = (v * 101n * 2n + 100n) / 200n;
  return v;
};
