const gt0 = (factId: string): Expr => ({ kind: "cmp", op: "gt", left: { kind: "fact", factId }, right: { kind: "money", cents: "0" } });

/** 2027-only rules whose amounts aren't price-indexed: in a projection they refuse when used */
export const NOT_PROJECTED: Record<string, { usedWhen: Expr; reason: string }> = {
  "us.federal.ptc": {
    usedWhen: { kind: "or", args: [gt0("marketplacePremiumsPaid"), gt0("advancePTC"), gt0("slcspAnnualPremium")] },
    reason:
      "the premium tax credit's applicable percentages are indexed to premium growth over income growth (§ 36B(b)(3)(A)(ii)) and its poverty line to HHS guidelines, neither of which is a price index the projection can carry forward",
  },
};
